insert into source_tier_config (tier, evidence_weight, max_confidence, can_penalize_alone, min_score_floor_alone, notes) values
  ('audited_ngo', 0.8, 0.85, true, 0, 'Index/ONG audité (FTI, KnowTheChain, BBFAW, Textile Exchange). Très fiable mais non régalien.'),
  ('crowd', 0.2, 0.3, false, 0.4, 'Contributif / militant non audité (ex: PETA). Compte faiblement, plafond bas, plancher haut.'),
  ('press', 0.35, 0.45, false, 0.3, 'Presse / allégations. Compte un peu, plafonné ; ne peut pas seule descendre un indicateur sous 0.30.'),
  ('regulatory', 1, 1, true, 0, 'Obligation légale (CSRD, devoir de vigilance, AMF, CbCR). Poids plein, aucun plancher.')
